//! Clipboard-based paste for macOS (recipe ported in spirit from Handy, MIT; see THIRD_PARTY.md).
//!
//! 1. Snapshot every item/type on the general pasteboard.
//! 2. Write the text marked `org.nspasteboard.TransientType` + `AutoGeneratedType`
//!    (clipboard managers skip these).
//! 3. Settle ~50 ms, send Cmd+V via CGEvent (virtual key 9, explicit command flag).
//! 4. After ~500 ms restore the snapshot, but only if `changeCount` is still ours.
//!
//! If Secure Input is on or Accessibility is missing, the text is left on the clipboard as
//! ordinary text and an error is returned so the daemon notifies the user.

use super::secure;
use crate::platform::Paster;
use anyhow::{anyhow, Result};
use objc2::rc::Retained;
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{NSPasteboard, NSPasteboardItem, NSPasteboardTypeString, NSPasteboardWriting};
use objc2_core_graphics::{CGEvent, CGEventFlags, CGEventSource, CGEventSourceStateID, CGEventTapLocation};
use objc2_foundation::{NSArray, NSData, NSString};
use std::sync::Mutex;
use std::time::Duration;

const TRANSIENT: &str = "org.nspasteboard.TransientType";
const AUTO_GENERATED: &str = "org.nspasteboard.AutoGeneratedType";
const KEY_V: u16 = 9;
const SETTLE: Duration = Duration::from_millis(50);
const RESTORE_AFTER: Duration = Duration::from_millis(500);

/// One pasteboard item: every (type, bytes) pair it carried.
type ItemSnapshot = Vec<(Retained<NSString>, Retained<NSData>)>;

pub struct MacPaster {
    /// Serialize pastes so snapshots/restores never interleave.
    lock: Mutex<()>,
}

impl MacPaster {
    pub fn new() -> Self {
        Self { lock: Mutex::new(()) }
    }
}

impl Default for MacPaster {
    fn default() -> Self {
        Self::new()
    }
}

fn snapshot(pb: &NSPasteboard) -> Vec<ItemSnapshot> {
    let mut out = Vec::new();
    if let Some(items) = pb.pasteboardItems() {
        for item in items.iter() {
            let mut entries = Vec::new();
            for ty in item.types().iter() {
                if let Some(data) = item.dataForType(&ty) {
                    entries.push((ty, data));
                }
            }
            if !entries.is_empty() {
                out.push(entries);
            }
        }
    }
    out
}

fn restore(pb: &NSPasteboard, snap: &[ItemSnapshot]) {
    pb.clearContents();
    if snap.is_empty() {
        return;
    }
    let items: Vec<Retained<NSPasteboardItem>> = snap
        .iter()
        .map(|entries| {
            let item = NSPasteboardItem::new();
            for (ty, data) in entries {
                item.setData_forType(data, ty);
            }
            item
        })
        .collect();
    let objs: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> =
        items.into_iter().map(ProtocolObject::from_retained).collect();
    pb.writeObjects(&NSArray::from_retained_slice(&objs));
}

/// Write `text`; `transient` adds the clipboard-manager skip markers. Returns the new changeCount.
fn write_text(pb: &NSPasteboard, text: &str, transient: bool) -> Result<isize> {
    pb.clearContents();
    let item = NSPasteboardItem::new();
    let ok = unsafe { item.setString_forType(&NSString::from_str(text), NSPasteboardTypeString) };
    if !ok {
        return Err(anyhow!("could not set pasteboard string"));
    }
    if transient {
        let empty = NSData::new();
        for t in [TRANSIENT, AUTO_GENERATED] {
            item.setData_forType(&empty, &NSString::from_str(t));
        }
    }
    let objs = [ProtocolObject::from_retained(item)];
    if !pb.writeObjects(&NSArray::from_retained_slice(&objs)) {
        return Err(anyhow!("pasteboard rejected the text"));
    }
    Ok(pb.changeCount())
}

fn send_cmd_v() -> Result<()> {
    let src = CGEventSource::new(CGEventSourceStateID::CombinedSessionState);
    for down in [true, false] {
        let ev = CGEvent::new_keyboard_event(src.as_deref(), KEY_V, down).ok_or_else(|| anyhow!("CGEventCreateKeyboardEvent failed"))?;
        CGEvent::set_flags(Some(&ev), CGEventFlags::MaskCommand);
        CGEvent::post(CGEventTapLocation::HIDEventTap, Some(&ev));
    }
    Ok(())
}

impl Paster for MacPaster {
    fn paste(&self, text: &str) -> Result<()> {
        let _g = self.lock.lock().unwrap_or_else(|e| e.into_inner());
        let pb = NSPasteboard::generalPasteboard();

        // Cases where we cannot paste: keep the text on the clipboard as normal (non-transient) text.
        if secure::secure_input_enabled() {
            write_text(&pb, text, false)?;
            return Err(anyhow!("Secure Input is active (password field?); text left on the clipboard, press Cmd+V"));
        }
        if !secure::accessibility_trusted() {
            write_text(&pb, text, false)?;
            return Err(anyhow!("Accessibility permission missing, cannot press Cmd+V; text left on the clipboard"));
        }

        let snap = snapshot(&pb);
        let ours = write_text(&pb, text, true)?;
        std::thread::sleep(SETTLE);
        if let Err(e) = send_cmd_v() {
            // Make the text usable: re-write as plain text so the user can paste manually.
            let _ = write_text(&pb, text, false);
            return Err(e.context("Cmd+V failed; text left on the clipboard"));
        }
        std::thread::sleep(RESTORE_AFTER);
        if pb.changeCount() == ours {
            restore(&pb, &snap);
        } else {
            tracing::debug!("pasteboard changed during paste; not restoring");
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Touches the real clipboard, so it is opt-in: `cargo test -- --ignored clipboard_roundtrip`.
    #[test]
    #[ignore]
    fn clipboard_roundtrip() {
        let pb = NSPasteboard::generalPasteboard();
        write_text(&pb, "capcom-original", false).unwrap();
        let snap = snapshot(&pb);
        assert!(!snap.is_empty());
        let ours = write_text(&pb, "capcom-transient", true).unwrap();
        assert_eq!(pb.changeCount(), ours);
        let now = unsafe { pb.stringForType(NSPasteboardTypeString) }.unwrap().to_string();
        assert_eq!(now, "capcom-transient");
        restore(&pb, &snap);
        let back = unsafe { pb.stringForType(NSPasteboardTypeString) }.unwrap().to_string();
        assert_eq!(back, "capcom-original");
    }
}
